"""Evidence evaluation for the calibration-limits study."""

import json


def _canonical(value):
    """Return a stable JSON representation used only for value comparison."""
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False)


def evaluate(request, evidence, policy):
    """Evaluate one request without mutating any input object."""
    required = policy.get("required_conditions", [])
    request_conditions = request.get("conditions", {})
    missing = sorted(name for name in required if name not in request_conditions)
    if missing:
        return {"status": "unknown", "value": None, "sources": [], "unknowns": missing}

    eligible = []
    for record in evidence:
        if record.get("claim") != request.get("claim"):
            continue
        if record.get("withdrawn", False):
            continue
        if policy.get("require_verified", False) and record.get("verified") is not True:
            continue
        record_conditions = record.get("conditions", {})
        if any(
            name not in record_conditions
            or record_conditions[name] != request_conditions[name]
            for name in required
        ):
            continue
        eligible.append(record)

    superseded = set()
    for record in eligible:
        replaced = record.get("supersedes", [])
        if isinstance(replaced, str):
            superseded.add(replaced)
        elif isinstance(replaced, (list, tuple, set)):
            superseded.update(replaced)
    eligible = [record for record in eligible if record.get("source") not in superseded]

    if not eligible:
        return {
            "status": "unknown",
            "value": None,
            "sources": [],
            "unknowns": ["no matching evidence"],
        }

    sources = sorted(record.get("source") for record in eligible)
    first_value = eligible[0].get("value")
    if any(_canonical(record.get("value")) != _canonical(first_value) for record in eligible[1:]):
        return {
            "status": "conflict",
            "value": None,
            "sources": sources,
            "unknowns": ["source disagreement"],
        }

    status = "unsupported" if isinstance(first_value, bool) and first_value is False else "supported"
    return {"status": status, "value": first_value, "sources": sources, "unknowns": []}


def _build_report():
    with open("requests.json", encoding="utf-8") as handle:
        requests = json.load(handle)
    with open("evidence.json", encoding="utf-8") as handle:
        evidence = json.load(handle)
    with open("policy.json", encoding="utf-8") as handle:
        policy = json.load(handle)
    return [evaluate(request, evidence, policy) for request in requests]


if __name__ == "__main__":
    with open("report.json", "w", encoding="utf-8") as handle:
        json.dump(_build_report(), handle, indent=2, ensure_ascii=False)
        handle.write("\n")
